-- Code generated by factory from specs/sales/list-unclosed-sales/spec.yaml. DO NOT EDIT.

-- name: ListUnclosedSales :many
SELECT t2.sales_date, t2.amount, t2.discount
FROM (
    SELECT t1.sales_date AS sales_date, t1.amount AS amount, t1.discount AS discount
    FROM daily_sales AS t1
    WHERE (t1.store_code = sqlc.arg(store_code)::int4)
      AND ((sqlc.narg(from_date)::date IS NULL) OR (t1.sales_date >= sqlc.narg(from_date)::date))
      AND (t1.closed_on IS NULL)
) AS t2
ORDER BY t2.sales_date
LIMIT 32;
